        public static void WriteSettings(string config)
        {
            string path = AppDomain.CurrentDomain.BaseDirectory + "config.txt";
            System.Diagnostics.Debug.WriteLine(path);
            System.IO.File.WriteAllText(path, config);
        }

        public static void ReadSettings()
        {
            string path = AppDomain.CurrentDomain.BaseDirectory + "config.txt";
            if (System.IO.File.Exists(path))
            {
                System.Diagnostics.Debug.WriteLine(path);
                Configs = System.IO.File.ReadAllText(path);
            }
            else
            {
                WriteSettings(Configs);
            }
        }

